import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for ZipArchiveOutputStream.closeArchiveEntry()
 */
public class ZipArchiveOutputStream_closeArchiveEntry_TriageGen2Test {

    private ByteArrayOutputStream out;
    private ZipArchiveOutputStream zos;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        zos = spy(new ZipArchiveOutputStream(out));
    }

    @After
    public void tearDown() throws IOException {
        zos.close();
    }

    /**
     * Test a standard successful close of an archive entry.
     * This covers the main path where Zip64 is not required.
     */
    @Test
    public void testCloseArchiveEntry_StandardPath() throws IOException {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        zos.putArchiveEntry(entry);
        zos.write("Hello World".getBytes());

        // We call the method under test
        zos.closeArchiveEntry();

        // Verify that internal state management occurred
        // Since we cannot easily access private fields like streamCompressor directly 
        // without reflection, we verify the behavior via side effects or spy interactions.
        verify(zos, atLeastOnce()).flush();
    }

    /**
     * Test the path where Zip64 is triggered.
     * We simulate large sizes to trigger the Zip64 logic inside handleSizesAndCrc.
     */
    @Test
    public void testCloseArchiveEntry_TriggersZip64() throws IOException {
        // Set mode to DEFAULT which allows Zip64 if needed
        zos.setUseZip64(Zip64Mode.DEFAULT);

        ZipArchiveEntry entry = new ZipArchiveEntry("large_file.txt");
        // Manually setting a huge size to force Zip64 logic in handleSizesAndCrc
        // Note: In a real scenario, the compressor would track this.
        // We simulate the entry being large.
        entry.setSize(Long.MAX_VALUE / 2); 

        zos.putArchiveEntry(entry);

        // We don't actually write MAX_VALUE bytes to avoid OutOfMemory, 
        // but we trigger the method.
        zos.closeArchiveEntry();

        // Verification of successful execution without exception
    }

    /**
     * Test the behavior when an IOException occurs during the process.
     * This ensures the exception propagates as expected.
     */
    @Test(expected = IOException.class)
    public void testCloseArchiveEntry_ThrowsIOException() throws IOException {
        ZipArchiveEntry entry = new ZipArchiveEntry("error.txt");
        zos.putArchiveEntry(entry);

        // Force an exception by spying on a method called within closeArchiveEntry
        doThrow(new IOException("Simulated IO Error")).when(zos).flush();

        zos.closeArchiveEntry();
    }

    /**
     * Test the branch coverage for different Zip64Modes.
     */
    @Test
    public void testCloseArchiveEntry_Zip64Disabled() throws IOException {
        // Force Zip64 to be OFF
        zos.setUseZip64(Zip64Mode. never());

        ZipArchiveEntry entry = new ZipArchiveEntry("no_zip64.txt");
        zos.putArchiveEntry(entry);
        zos.write("data".getBytes());

        zos.closeArchiveEntry();
        // If no exception is thrown, the logic for handling effectiveMode is covered
    }

    /**
     * Test the branch coverage for Zip64Mode.DIGITAL.
     */
    @Test
    public void testCloseArchiveEntry_Zip64Digital() throws IOException {
        zos.setUseZip64(Zip64Mode.DIGITAL);

        ZipArchiveEntry entry = new ZipArchiveEntry("digital.txt");
        zos.putArchiveEntry(entry);
        zos.write("data".getBytes());

        zos.closeArchiveEntry();
    }

    /**
     * Test the path where the stream might be empty or entry has no data.
     */
    @Test
    public void testCloseArchiveEntry_EmptyEntry() throws IOException {
        ZipArchiveEntry entry = new ZipArchiveEntry("empty.txt");
        zos.putArchiveEntry(entry);

        // No write() called
        zos.closeArchiveEntry();

        // Verify that the method completes successfully for empty files
    }
}
